#!/usr/bin/env bash
#
# The hand edits to the generated Android project are still there.
#
# `app/src-tauri/gen/` is gitignored — it is generated by `tauri android init`
# and regenerating it is normal. But the USB host entries are NOT generated:
# they are added by scripts/android-usb-host.sh, they are not expressible in
# tauri.conf.json, and nothing in the build notices when they are missing.
#
# Without them the app still compiles, installs and runs, and Bluetooth keeps
# working, which is what makes a missing line read as "USB is broken" rather
# than "a manifest line is missing". A fresh clone regenerates the manifest and
# would land straight back in it, which is what this check exists to prevent.
#
# The two camera lines are checked too: the Send form scans Zcash addresses
# and ZIP 321 requests, and without the permission Android denies the camera
# with no dialog.
#
# Run by scripts/check.sh and by app/scripts/android-release.sh, and a no-op
# when gen/android has not been generated.

set -uo pipefail
cd "$(dirname "$0")/.."

MANIFEST="app/src-tauri/gen/android/app/src/main/AndroidManifest.xml"

if [[ ! -f "$MANIFEST" ]]; then
    echo "   gen/android not generated here; nothing to check"
    exit 0
fi

missing=()
# Without the feature Android can hand back an empty device list; without the
# filter file the manifest's @xml/device_filter reference dangles and the
# attach intent cannot fire. Both leave BLE working.
grep -q 'android.hardware.usb.host' "$MANIFEST" || missing+=("uses-feature android.hardware.usb.host (run scripts/android-usb-host.sh)")
[[ -f "app/src-tauri/gen/android/app/src/main/res/xml/device_filter.xml" ]] \
    || missing+=("res/xml/device_filter.xml (run scripts/android-usb-host.sh)")

grep -q 'android.permission.CAMERA' "$MANIFEST" || missing+=("uses-permission android.permission.CAMERA (run scripts/android-usb-host.sh)")
grep -q 'android.hardware.camera"' "$MANIFEST" || missing+=("uses-feature android.hardware.camera (run scripts/android-usb-host.sh)")

if (( ${#missing[@]} )); then
    echo "The generated Android project is missing hand-added entries:"
    for m in "${missing[@]}"; do echo "  - $m"; done
    echo
    echo "Run: ./scripts/android-usb-host.sh"
    echo
    echo "See app/ANDROID.md. Each failure here is silent at runtime: USB comes"
    echo "back empty while BLE keeps working, which reads as a broken cable"
    echo "rather than a manifest."
    exit 1
fi

echo "   USB host and camera entries present"
